<?php include 'views/layouts/header.php'; $calendar=$calendar??['month'=>date('Y-m'),'events'=>[]]; $current=new DateTimeImmutable($calendar['month'].'-01'); $prev=$current->modify('-1 month')->format('Y-m');$next=$current->modify('+1 month')->format('Y-m');$months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']; ?>
<div class="container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1">Calendario</h1><p class="text-muted mb-0">Vencimientos y visitas técnicas registrados en el sistema.</p></div><a href="<?php echo url('dashboard'); ?>" class="btn btn-outline-primary">Volver al dashboard</a></div><div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-4"><a class="btn btn-light" href="?mes=<?php echo $prev; ?>"><i class="fas fa-chevron-left"></i></a><strong class="fs-5"><?php echo ucfirst($months[(int)$current->format('n')-1]).' '.$current->format('Y'); ?></strong><a class="btn btn-light" href="?mes=<?php echo $next; ?>"><i class="fas fa-chevron-right"></i></a></div><?php if(!$calendar['events']): ?><p class="text-center text-muted py-5">No hay eventos registrados en este mes.</p><?php else: ?><div class="list-group list-group-flush"><?php foreach($calendar['events'] as $event): ?><div class="list-group-item d-flex align-items-center gap-3 py-3"><span class="badge <?php echo $event['tipo']==='vencido'?'text-bg-danger':($event['tipo']==='visita'?'text-bg-primary':'text-bg-warning'); ?>"><?php echo htmlspecialchars(date('d',strtotime($event['fecha']))); ?></span><div><strong><?php echo htmlspecialchars($event['titulo']); ?></strong><div class="small text-muted"><?php echo htmlspecialchars($event['detalle']); ?></div></div><span class="ms-auto small text-muted"><?php echo htmlspecialchars($event['fecha']); ?></span></div><?php endforeach; ?></div><?php endif; ?></div></div></div>
<?php include 'views/layouts/footer.php'; ?>
